'use strict';
let D,tab='overview',query='';
const $=s=>document.querySelector(s),fmt=(n,d=1)=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:d}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sum=(rows,key)=>rows.reduce((a,r)=>a+r[key],0);
function holes(){return D.collar.filter(h=>(!$('#site').value||h.site===$('#site').value)&&(!$('#rig').value||D.shifts.some(s=>s.hole===h.id&&s.rig===$('#rig').value)));}
function shifts(){let ids=new Set(holes().map(h=>h.id));return D.shifts.filter(s=>ids.has(s.hole)&&(!$('#rig').value||s.rig===$('#rig').value));}
function depth(id){let rows=D.shifts.filter(s=>s.hole===id);return rows.length?Math.max(...rows.map(s=>s.to)):null;}
function status(h){if(h.finish)return ['Дууссан',''];if(D.shifts.some(s=>s.hole===h.id))return ['Өрөмдөж байна','active'];return ['Төлөвлөсөн','planned'];}
function kpis(){let s=shifts(),h=holes(),total=sum(s,'meters'),dt=sum(s,'dt'),hours=sum(s,'hours');return `<div class="kpis">${[
['Тайлант хугацаанд өрөмдсөн',fmt(total),'м',`${s.length} ээлж · давхардлыг хассан`],
['Бүртгэлтэй цооног',h.length,'ш',`${h.filter(x=>x.finish).length} дууссан · collar бүртгэлээр`],
['Өрөмдлөгийн ашиглалт',hours?fmt(dt/hours*100):'—','%',`DT ${fmt(dt)} / нийт ${fmt(hours)} цаг`],
['Дундаж хурд · ROP',dt?fmt(total/dt,2):'—','м/ц',`Өрөмдсөн метр / DT цаг`]
].map(([label,value,unit,note])=>`<article class="kpi"><div class="label">${label}</div><div class="value">${value} <small>${unit}</small></div><div class="note">${note}</div></article>`).join('')}</div>`;}
function chart(){let s=shifts();if(!s.length)return '<div class="empty">Ээлжийн өгөгдөл байхгүй.</div>';let dates=[...new Set(D.shifts.map(x=>x.date))].sort(),max=Math.max(30,Math.ceil(Math.max(...dates.flatMap(date=>['C-1800','CSD-1300'].map(rig=>sum(s.filter(r=>r.date===date&&r.rig===rig),'meters'))))/30)*30),W=680,H=230,pad=34,bw=15,step=(W-2*pad)/dates.length;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Өдөр бүрийн өрөмдсөн метрийг хоёр өрмөөр харуулсан баганан график">`;for(let n=0;n<=max;n+=30){let y=H-35-n/max*175;svg+=`<line x1="${pad}" x2="${W-pad}" y1="${y}" y2="${y}" stroke="#e8eded"/><text x="0" y="${y+4}">${n}</text>`;}dates.forEach((date,i)=>{let x=pad+i*step+step/2;['C-1800','CSD-1300'].forEach((rig,j)=>{let v=sum(s.filter(r=>r.date===date&&r.rig===rig),'meters'),height=v/max*175;svg+=`<rect x="${x+(j-1)*17}" y="${H-35-height}" width="${bw}" height="${height}" rx="2" fill="${j?'#dc8a3b':'#128875'}"><title>${date} · ${rig}: ${fmt(v)} м</title></rect>`;});svg+=`<text x="${x}" y="${H-12}" text-anchor="middle">${date.slice(-2)}</text>`;});return svg+'</svg><div class="legend">Өдөр + шөнийн ээлжийн нийлбэр</div>';}
function rigs(){let s=shifts();return ['C-1800','CSD-1300'].map(rig=>{let rows=s.filter(x=>x.rig===rig),dt=sum(rows,'dt'),hours=sum(rows,'hours');return `<div class="rig-card"><div class="rig-title"><span>${rig}</span><span>${fmt(sum(rows,'meters'))} <small>м</small></span></div><div class="rig-stats"><span>${rows.length} ээлж</span><span>ROP ${dt?fmt(sum(rows,'meters')/dt,2):'—'} м/ц</span></div><div class="track"><span style="width:${hours?dt/hours*100:0}%;background:${rig==='C-1800'?'#128875':'#dc8a3b'}"></span></div><div class="rig-stats"><span>Ашиглалт ${hours?fmt(dt/hours*100):'—'}%</span><span>ST ${fmt(sum(rows,'st'))} цаг</span></div></div>`;}).join('');}
function holeTable(){let h=holes().filter(x=>x.id.toLowerCase().includes(query.toLowerCase()));return `<div class="table-scroll"><table><thead><tr><th>Цооног</th><th>Талбай</th><th>Өрөм</th><th>Төлөв¹</th><th>Төлөвлөсөн</th><th>Ээлжийн гүн²</th><th>Collar гүн</th><th>Ахиц²</th></tr></thead><tbody>${h.map(x=>{let d=depth(x.id),st=status(x),rig=D.shifts.find(s=>s.hole===x.id)?.rig,percent=d!=null&&x.plan?d/x.plan*100:null;return `<tr><td><button class="hole-link" data-hole="${esc(x.id)}">${esc(x.id)} ↗</button></td><td>${esc(x.site)}</td><td>${esc(rig||'—')}</td><td><span class="badge ${st[1]}">${st[0]}</span></td><td>${fmt(x.plan)} м</td><td>${fmt(d)} м</td><td>${fmt(x.collarDepth)} м</td><td><div class="mini"><div class="track"><span style="width:${Math.min(percent||0,100)}%"></span></div>${percent==null?'—':fmt(percent)+'%'}</div></td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">Цооног олдсонгүй.</td></tr>'}</tbody></table></div><p class="sub" style="margin:12px 0 0">¹ Collar-ийн дууссан огноогоор. ² Тайлант хугацааны ээлжийн хамгийн их гүн / төлөвлөгөө; 100%-аас давах боломжтой.</p>`;}
function alerts(){let notes=[];for(const h of holes()){let d=depth(h.id);if(h.collarDepth!=null&&d!=null&&Math.abs(h.collarDepth-d)>0.01)notes.push(h.id+': collar '+fmt(h.collarDepth)+' м / ээлж '+fmt(d)+' м');let rows=D.shifts.filter(s=>s.hole===h.id).sort((a,b)=>b.date.localeCompare(a.date));if(h.finish&&rows.length&&h.finish>rows[0].date)notes.push(h.id+': collar дууссан '+h.finish+' / ээлжийн сүүлийн огноо '+rows[0].date);}notes.push(...(D.syncWarnings||[]));return notes.length?'<div class="alert"><span>△</span><div><strong>Эх сурвалжийн зөрүүг шалгах шаардлагатай</strong>'+notes.map(esc).join(' · ')+' <a href="#sources" class="source-link" data-go="sources">Дэлгэрэнгүй →</a></div></div>':'';}
function shiftTable(){let s=shifts().filter(x=>(x.hole+' '+x.driller+' '+x.date).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||a.rig.localeCompare(b.rig));return `<div class="table-scroll"><table><thead><tr><th>Огноо / ээлж</th><th>Өрөм</th><th>Цооног</th><th>Өрөмдөгч</th><th>Гүний интервал</th><th>Метр</th><th>DT / ST цаг</th><th>ROP м/ц</th></tr></thead><tbody>${s.map(x=>`<tr title="${esc(x.notes)}"><td>${x.date}<br><small>${esc(x.shift)}</small></td><td>${x.rig}</td><td><button class="hole-link" data-hole="${x.hole}">${x.hole}</button></td><td>${esc(x.driller)}</td><td>${fmt(x.from)} – ${fmt(x.to)}</td><td><strong>${fmt(x.meters)}</strong></td><td>${fmt(x.dt)} / ${fmt(x.st)}</td><td>${x.dt?fmt(x.meters/x.dt,2):'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Ээлж олдсонгүй.</td></tr>'}</tbody></table></div>`;}
function sources(){return '<section class="panel"><h2>Өгөгдлийн эх сурвалж</h2><p class="sub">Python шинэчлэлтийн урсгал · '+esc(D.period)+'</p><div class="source-list"><div class="source-row"><a class="source-link" href="'+D.collarUrl+'" target="_blank" rel="noopener">Collar бүртгэл ↗</a><p>Төлөвлөгөө, координат, эхэлсэн / дууссан огноо. '+D.collar.length+' цооног; Hole ID-аар давхардлыг хассан.</p></div><div class="source-row"><a class="source-link" href="'+D.shiftUrl+'" target="_blank" rel="noopener">Ээлжийн тайлан ↗</a><p>'+D.shifts.length+' ээлж · '+fmt(sum(D.shifts,'meters'))+' м. Ижил ээлжүүдийг өрөм, огноо, ээлж, цооногийн дугаараар нэг удаа тооцсон.</p></div></div></section>'+alerts()+'<section class="panel"><h2>Тооцоолол & шинэчлэлт</h2><p>Python файл Drive эсвэл local CSV/XLSX-ээс өгөгдөл уншиж шалгана. GitHub руу push хийхэд GitHub Actions энэ сайтыг шинэчилнэ. Нээлттэй dashboard 60 секунд тутам өгөгдлөө дахин уншина.</p><p>Өрөмдсөн метр = ээлжийн метрийн нийлбэр. Ашиглалт = DT / нийт цаг. ROP = метр / DT. Ахиц = сүүлийн ээлжийн гүн / төлөвлөсөн гүн. Дууссан төлөв нь collar бүртгэлээр.</p><p>Хоосон утгыг — гэж харуулна. Өгөгдөл боловсруулах алдаа гарвал өмнөх өгөгдөл хадгалагдана. Давхардсан тайлан зөрвөл шинэ файлын мөрийг хадгалж, зөрүүг тэмдэглэнэ.</p><p>Координатын систем баталгаажаагүй тул газрын зураг дээр байрлуулаагүй.</p></section>';}
function render(){if(!D)return;let content=kpis();if(tab==='overview')content+=`<div class="grid"><section class="panel"><div class="panel-head"><h2>Өдөр бүрийн гүйцэтгэл</h2><span class="legend"><i class="teal"></i>C-1800<i class="orange"></i>CSD-1300</span></div><p class="sub">Өрөмдсөн метр · ээлжийн бүртгэл</p>${chart()}</section><section class="panel"><h2>Өрмийн гүйцэтгэл</h2><p class="sub">Сонгосон талбайн ээлжүүд</p>${rigs()}</section></div>${alerts()}<section class="panel"><div class="panel-head"><h2>Цооногийн ахиц</h2><button class="button" data-go="holes">Бүх бүртгэл →</button></div><p class="sub">Төлөвлөгөө ба бодит гүний харьцуулалт</p>${holeTable()}</section>`;if(tab==='holes')content+=`<section class="panel"><div class="panel-head"><h2>Цооногийн бүртгэл</h2><input class="search" aria-label="Цооног хайх" placeholder="Цооног хайх…" value="${esc(query)}"></div><p class="sub">Цооногийн дугаарыг дарж дэлгэрэнгүй болон Drive баримт нээнэ.</p><div id="table">${holeTable()}</div></section>${alerts()}`;if(tab==='shifts')content+=`<section class="panel"><div class="panel-head"><h2>Ээлжийн бүртгэл</h2><input class="search" aria-label="Ээлж хайх" placeholder="Цооног, нэр, огноо…" value="${esc(query)}"></div><p class="sub">Ажлын тайлбарыг мөр дээр хулганаа байрлуулж харна.</p><div id="table">${shiftTable()}</div></section>`;if(tab==='sources')content=sources();$('#app').innerHTML=content;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('.search')?.addEventListener('input',e=>{query=e.target.value;$('#table').innerHTML=tab==='holes'?holeTable():shiftTable();});}
function openHole(id){let h=D.collar.find(x=>x.id===id),f=D.folderMap[id],st=status(h),d=depth(id);$('#detail-body').innerHTML=`<small>ЦООНОГИЙН ДЭЛГЭРЭНГҮЙ</small><h2 style="font-size:25px">${h.id}</h2><p>${h.site} · <span class="badge ${st[1]}">${st[0]}</span></p><div class="detail-grid">${[['Төлөвлөсөн гүн',fmt(h.plan)+' м'],['Ээлжийн сүүлийн гүн',fmt(d)+' м'],['Collar эцсийн гүн',fmt(h.collarDepth)+' м'],['Эхэлсэн / дууссан',`${h.start||'—'} / ${h.finish||'—'}`],['E / N / Z',`${fmt(h.e,3)} / ${fmt(h.n,3)} / ${fmt(h.z,3)}`],['Азимут / хазайлт',`${fmt(h.az)}° / ${fmt(h.dip)}°`],['Керний гарц',h.recovery==null?'—':fmt(h.recovery)+'%'],['Керний хайрцаг',fmt(h.boxes,0)]].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><h3>Drive баримтын хавтас</h3><div class="folder-links">${f?f.folders.map(x=>`<a href="${x.url}" target="_blank" rel="noopener">${esc(x.name)} ↗</a>`).join(''):'Энэ цооногийн хавтас олдоогүй.'}</div>`;$('#detail').showModal();}
document.addEventListener('click',e=>{let t=e.target.closest('[data-tab],[data-go]');if(t){e.preventDefault();tab=t.dataset.tab||t.dataset.go;query='';render();}let h=e.target.closest('[data-hole]');if(h)openHole(h.dataset.hole);});
$('#site').addEventListener('change',render);$('#rig').addEventListener('change',render);$('.close').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#export').addEventListener('click',()=>{let records=tab==='shifts'?shifts().filter(x=>(x.hole+' '+x.driller+' '+x.date).toLowerCase().includes(query.toLowerCase())):holes().filter(x=>x.id.toLowerCase().includes(query.toLowerCase())).map(h=>({...h,shiftDepth:depth(h.id),status:status(h)[0]}));if(!records.length){alert('Татах бүртгэл байхгүй.');return;}let keys=Object.keys(records[0]),cell=x=>'"'+String(x??'').replace(/"/g,'""')+'"',csv='\uFEFF'+[keys,...records.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`drilling-${tab}-${D.asOf}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
async function refreshData(){try{let r=await fetch('data.json',{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error('HTTP '+r.status);let data=await r.json(),changed=JSON.stringify(data)!==JSON.stringify(D);D=data;$('#drive').href=D.driveUrl;$('.period strong').textContent=D.period;$('.snapshot').textContent='◷ Сүүлд шинэчилсэн: '+(D.updatedAt||D.asOf)+' · Веб 60 секунд тутам өгөгдлөө шалгана.';$('.aside-bottom small').textContent=D.asOf+' · Python sync';if(changed)render();}catch(e){$('.snapshot').textContent='Өгөгдөл шинэчлэхэд алдаа гарлаа. Өмнөх өгөгдлийг харуулж байна.';if(!D)$('#app').textContent='Өгөгдөл ачааллахад алдаа гарлаа: '+e.message;}}
refreshData();setInterval(refreshData,60000);
